args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?director ?country ?directorLabel ?countryLabel WHERE {
  dbr:La_Yuma dbo:director ?director .
  {
    ?director dbo:birthPlace ?bp .
    ?bp dbo:country ?country .
  }
  UNION
  {
    ?director dbo:country ?country .
  }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(lang(?directorLabel) = "en") }
  OPTIONAL { ?country rdfs:label ?countryLabel . FILTER(lang(?countryLabel) = "en") }
}

